<?php require_once "../db.php"; require_role("Student");$uid=current_id();$st=$conn->prepare("SELECT h.*,q.title,q.subject FROM quiz_history h JOIN quiz q ON q.id=h.quiz_id WHERE h.student_id=? ORDER BY h.id DESC");$st->bind_param("i",$uid);$st->execute();$r=$st->get_result();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quiz History</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/student_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><h2 class="fw-bold">Quiz History</h2><div class="card panel-card"><div class="card-body table-responsive"><table class="table align-middle"><thead><tr><th>#</th><th>Quiz</th><th>Subject</th><th>Score</th><th>Percentage</th><th>Date</th><th></th></tr></thead><tbody><?php $n=1;while($d=$r->fetch_assoc()):$p=$d["total_questions"]?round($d["score"]/$d["total_questions"]*100,1):0;?><tr><td><?=$n++?></td><td><?=e($d["title"])?></td><td><?=e($d["subject"])?></td><td><?=$d["score"]?>/<?=$d["total_questions"]?></td><td><span class="badge bg-<?=$p>=50?"success":"danger"?>"><?=$p?>%</span></td><td><?=$d["created_at"]?></td><td><a class="btn btn-sm btn-outline-primary" href="quiz_result.php?id=<?=$d["id"]?>">View</a></td></tr><?php endwhile;?></tbody></table></div></div></div></main></div></div></body></html>
